using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {public static partial class LeftFactoryDistrictBuilder {
static float RearBoundary(float x){if(x<=-540)return 970;if(x>=-300)return 1030;return 970+(x+540)*.25f;}
struct CutVertex {public Vector3 p;public Vector2 uv;}
static Mesh CutRearRoad(Mesh src,Transform tr){var vertices=src.vertices;var tex=src.uv;var output=new List<Vector3>();var uvs=new List<Vector2>();var indices=new List<int>[src.subMeshCount];for(int sub=0;sub<src.subMeshCount;sub++){indices[sub]=new List<int>();var tris=src.GetTriangles(sub);for(int i=0;i<tris.Length;i+=3){var input=new List<CutVertex>();for(int k=0;k<3;k++){int n=tris[i+k];input.Add(new CutVertex{p=tr.TransformPoint(vertices[n]),uv=tex.Length>n?tex[n]:Vector2.zero});}var poly=new List<CutVertex>();for(int k=0;k<3;k++){var a=input[k];var b=input[(k+1)%3];bool ia=a.p.z<=RearBoundary(a.p.x)+8,ib=b.p.z<=RearBoundary(b.p.x)+8;if(ia)poly.Add(a);if(ia!=ib){float low=0,high=1;for(int j=0;j<18;j++){float mid=(low+high)*.5f;var p=Vector3.Lerp(a.p,b.p,mid);bool inside=p.z<=RearBoundary(p.x)+8;if(inside==ia)low=mid;else high=mid;}float t=(low+high)*.5f;poly.Add(new CutVertex{p=Vector3.Lerp(a.p,b.p,t),uv=Vector2.Lerp(a.uv,b.uv,t)});}}if(poly.Count<3)continue;int start=output.Count;foreach(var v in poly){output.Add(tr.InverseTransformPoint(v.p));uvs.Add(v.uv);}for(int k=1;k<poly.Count-1;k++)indices[sub].AddRange(new[]{start,start+k,start+k+1});}}var mesh=new Mesh{name="FactoryRoads_TrimmedAtRearBoundary",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(output);mesh.SetUVs(0,uvs);mesh.subMeshCount=indices.Length;for(int sub=0;sub<indices.Length;sub++)mesh.SetTriangles(indices[sub],sub);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
[MenuItem("Anseong/Art/Trim Yellow Rear Factory Area")]
public static void TrimYellowRearFactoryArea(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/RearVisibilityTrim";Folder(folder);var factory=GameObject.Find("Factory_HighlightedLZone");if(!factory)throw new Exception("Missing highlighted factory");var remove=new List<GameObject>();foreach(var t in factory.GetComponentsInChildren<Transform>())if(PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject)){var b=B(t.gameObject);if(b.center.z>RearBoundary(b.center.x)+8)remove.Add(t.gameObject);}var report=new System.Text.StringBuilder("# Rear factory visibility trim\n\nYellow reference area interpreted as beyond the existing cross-site boundary road: Z970 at west, diagonal to Z1030 at east. Road and8m half-width retained. Placed prefab instances only removed; shared source assets remain. Roads beyond boundary geometrically clipped. Staff dormitory campus behind boundary removed from this scene. Terrain, sea, quay, combat area and near factory unchanged.\n\nRemoved factory instances:\n");foreach(var g in remove){report.AppendLine("- "+g.name+" "+B(g).center);Object.DestroyImmediate(g);}var campus=GameObject.Find("StaffDormitoryCampus");bool removedCampus=false;if(campus){Object.DestroyImmediate(campus);removedCampus=true;}var roads=GameObject.Find("FactoryRoads_RefinedJunctions");if(!roads)throw new Exception("Missing active road network");var mesh=CutRearRoad(roads.GetComponent<MeshFilter>().sharedMesh,roads.transform);AssetDatabase.CreateAsset(mesh,folder+"/RetainedBoundaryRoads.asset");roads.GetComponent<MeshFilter>().sharedMesh=mesh;roads.name="FactoryRoads_RetainedToRearBoundary";int remainingOutside=0;foreach(var t in factory.GetComponentsInChildren<Transform>())if(PrefabUtility.IsOutermostPrefabInstanceRoot(t.gameObject)){var b=B(t.gameObject);if(b.center.z>RearBoundary(b.center.x)+8)remainingOutside++;}if(remainingOutside>0)throw new Exception("Far structures remain");report.AppendLine("\nRemoved="+remove.Count+" campusRemoved="+removedCampus+" remainingBeyondBoundary="+remainingOutside+"\n");File.WriteAllText(folder+"/TrimReport.md",report.ToString());AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"RearTrim_Main");var go=new GameObject("TrimPreviewCamera");var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.transform.position=new Vector3(0,65,-120);cam.transform.rotation=Quaternion.Euler(-2,0,0);Capture(cam,"RearTrim_RobotHeight");Object.DestroyImmediate(go);Debug.Log("REAR_TRIM_PASS removed="+remove.Count+" campusRemoved="+removedCampus+" outside=0 boundaryRoadPreserved=true");}
}}